using std::string;
static DBusConnection *bus;
static string service,phase="Отключено";
static bool selected=false,running=true;
static unsigned revision=1;
static std::vector<unsigned char> pixels;
static const char *menuIface="com.canonical.dbusmenu";
static void text(DBusMessageIter *i,const string&s,int type=DBUS_TYPE_STRING){const char*p=s.c_str();dbus_message_iter_append_basic(i,type,&p);}
static void integer(DBusMessageIter*i,int n){dbus_message_iter_append_basic(i,DBUS_TYPE_INT32,&n);}
static void uintv(DBusMessageIter*i,unsigned n){dbus_message_iter_append_basic(i,DBUS_TYPE_UINT32,&n);}
static void boolean(DBusMessageIter*i,bool v){dbus_bool_t b=v;dbus_message_iter_append_basic(i,DBUS_TYPE_BOOLEAN,&b);}
static void pixmap(DBusMessageIter*i,bool icon){DBusMessageIter a,s,b;dbus_message_iter_open_container(i,DBUS_TYPE_ARRAY,"(iiay)",&a);if(icon&&!pixels.empty()){dbus_message_iter_open_container(&a,DBUS_TYPE_STRUCT,nullptr,&s);integer(&s,64);integer(&s,64);dbus_message_iter_open_container(&s,DBUS_TYPE_ARRAY,"y",&b);const unsigned char*p=pixels.data();dbus_message_iter_append_fixed_array(&b,DBUS_TYPE_BYTE,&p,pixels.size());dbus_message_iter_close_container(&s,&b);dbus_message_iter_close_container(&a,&s);}dbus_message_iter_close_container(i,&a);}
static string label(int id){return id==1?"Открыть Nekobox YTM":id==3?(phase=="Отключено"?"Подключить":"Отключить"):id==5?"Выход":"";}
static void property(DBusMessageIter*i,const string&name,const string&kind,const string&value="",bool flag=false){DBusMessageIter e,v;dbus_message_iter_open_container(i,DBUS_TYPE_DICT_ENTRY,nullptr,&e);text(&e,name);dbus_message_iter_open_container(&e,DBUS_TYPE_VARIANT,kind.c_str(),&v);if(kind=="b")boolean(&v,flag);else if(kind=="u")uintv(&v,name=="WindowId"?0:4);else if(kind=="as"){DBusMessageIter a;dbus_message_iter_open_container(&v,DBUS_TYPE_ARRAY,"s",&a);dbus_message_iter_close_container(&v,&a);}else if(kind=="a(iiay)")pixmap(&v,name=="IconPixmap");else if(kind=="(sa(iiay)ss)"){DBusMessageIter t;dbus_message_iter_open_container(&v,DBUS_TYPE_STRUCT,nullptr,&t);text(&t,"");pixmap(&t,false);text(&t,"Nekobox YTM");text(&t,phase);dbus_message_iter_close_container(&v,&t);}else text(&v,value,kind=="o"?DBUS_TYPE_OBJECT_PATH:DBUS_TYPE_STRING);dbus_message_iter_close_container(&e,&v);dbus_message_iter_close_container(i,&e);}
static void itemprops(DBusMessageIter*i,int id){DBusMessageIter a;dbus_message_iter_open_container(i,DBUS_TYPE_ARRAY,"{sv}",&a);if(id==2||id==4)property(&a,"type","s","separator");else if(id!=0){property(&a,"label","s",label(id));property(&a,"enabled","b","",id!=3||selected||phase!="Отключено");}property(&a,"visible","b","",true);if(id==0)property(&a,"children-display","s","submenu");dbus_message_iter_close_container(i,&a);}
static void layout(DBusMessageIter*i,int id,int depth){DBusMessageIter s,a,v;dbus_message_iter_open_container(i,DBUS_TYPE_STRUCT,nullptr,&s);integer(&s,id);itemprops(&s,id);dbus_message_iter_open_container(&s,DBUS_TYPE_ARRAY,"v",&a);if(id==0&&depth!=0)for(int n=1;n<=5;n++){dbus_message_iter_open_container(&a,DBUS_TYPE_VARIANT,"(ia{sv}av)",&v);layout(&v,n,0);dbus_message_iter_close_container(&a,&v);}dbus_message_iter_close_container(&s,&a);dbus_message_iter_close_container(i,&s);}
static void emit(const char*s){std::cout<<s<<std::endl;}
static void action(int id){if(id==1)emit("показать");if(id==3)emit("подключение");if(id==5)emit("выход");}
static void send(DBusMessage*m){dbus_connection_send(bus,m,nullptr);dbus_message_unref(m);dbus_connection_flush(bus);}
static void changed(){auto m=dbus_message_new_signal("/MenuBar",menuIface,"LayoutUpdated");DBusMessageIter i;dbus_message_iter_init_append(m,&i);uintv(&i,++revision);integer(&i,0);send(m);m=dbus_message_new_signal("/StatusNotifierItem","org.kde.StatusNotifierItem","NewToolTip");send(m);}
static void allprops(DBusMessageIter*i,bool menu){DBusMessageIter a;dbus_message_iter_open_container(i,DBUS_TYPE_ARRAY,"{sv}",&a);if(menu){property(&a,"Version","u");property(&a,"TextDirection","s","ltr");property(&a,"Status","s","normal");property(&a,"IconThemePath","as");}else{property(&a,"Category","s","ApplicationStatus");property(&a,"Id","s","nekobox-ytm-android-linux");property(&a,"Title","s","Nekobox YTM");property(&a,"Status","s","Active");property(&a,"WindowId","u");property(&a,"IconName","s","");property(&a,"IconPixmap","a(iiay)");property(&a,"OverlayIconName","s","");property(&a,"OverlayIconPixmap","a(iiay)");property(&a,"AttentionIconName","s","");property(&a,"AttentionIconPixmap","a(iiay)");property(&a,"AttentionMovieName","s","");property(&a,"IconThemePath","s","");property(&a,"ToolTip","(sa(iiay)ss)");property(&a,"ItemIsMenu","b","",false);property(&a,"Menu","o","/MenuBar");}dbus_message_iter_close_container(i,&a);}
static DBusHandlerResult handle(DBusConnection*,DBusMessage*m,void*){
 if(dbus_message_get_type(m)!=DBUS_MESSAGE_TYPE_METHOD_CALL)return DBUS_HANDLER_RESULT_NOT_YET_HANDLED;
 string method=dbus_message_get_member(m),iface=dbus_message_get_interface(m)?dbus_message_get_interface(m):"",path=dbus_message_get_path(m);bool menu=path=="/MenuBar";
 auto reply=dbus_message_new_method_return(m);DBusMessageIter out,in;dbus_message_iter_init_append(reply,&out);dbus_message_iter_init(m,&in);
 if(iface=="org.freedesktop.DBus.Introspectable"){
  const char*xml=R"XML(<node><interface name="org.freedesktop.DBus.Properties"><method name="GetAll"><arg type="s" direction="in"/><arg type="a{sv}" direction="out"/></method><method name="Get"><arg type="s" direction="in"/><arg type="s" direction="in"/><arg type="v" direction="out"/></method></interface><interface name="org.kde.StatusNotifierItem"><method name="Activate"><arg type="i" direction="in"/><arg type="i" direction="in"/></method><method name="SecondaryActivate"><arg type="i" direction="in"/><arg type="i" direction="in"/></method><method name="ContextMenu"><arg type="i" direction="in"/><arg type="i" direction="in"/></method><property name="Menu" type="o" access="read"/><property name="ItemIsMenu" type="b" access="read"/><property name="IconPixmap" type="a(iiay)" access="read"/><property name="Category" type="s" access="read"/><property name="Id" type="s" access="read"/><property name="Title" type="s" access="read"/><property name="Status" type="s" access="read"/><property name="WindowId" type="u" access="read"/><property name="IconName" type="s" access="read"/><property name="OverlayIconName" type="s" access="read"/><property name="OverlayIconPixmap" type="a(iiay)" access="read"/><property name="AttentionIconName" type="s" access="read"/><property name="AttentionIconPixmap" type="a(iiay)" access="read"/><property name="AttentionMovieName" type="s" access="read"/><property name="ToolTip" type="(sa(iiay)ss)" access="read"/><property name="IconThemePath" type="s" access="read"/><signal name="NewToolTip"/><signal name="NewIcon"/><signal name="NewTitle"/><signal name="NewStatus"><arg type="s"/></signal></interface><interface name="com.canonical.dbusmenu"><method name="GetLayout"><arg type="i" direction="in"/><arg type="i" direction="in"/><arg type="as" direction="in"/><arg type="u" direction="out"/><arg type="(ia{sv}av)" direction="out"/></method><method name="GetGroupProperties"><arg type="ai" direction="in"/><arg type="as" direction="in"/><arg type="a(ia{sv})" direction="out"/></method><method name="GetProperty"><arg type="i" direction="in"/><arg type="s" direction="in"/><arg type="v" direction="out"/></method><method name="Event"><arg type="i" direction="in"/><arg type="s" direction="in"/><arg type="v" direction="in"/><arg type="u" direction="in"/></method><method name="EventGroup"><arg type="a(isvu)" direction="in"/><arg type="ai" direction="out"/></method><method name="AboutToShow"><arg type="i" direction="in"/><arg type="b" direction="out"/></method><method name="AboutToShowGroup"><arg type="ai" direction="in"/><arg type="ai" direction="out"/><arg type="ai" direction="out"/></method><signal name="LayoutUpdated"><arg type="u"/><arg type="i"/></signal><property name="Version" type="u" access="read"/><property name="TextDirection" type="s" access="read"/><property name="Status" type="s" access="read"/><property name="IconThemePath" type="as" access="read"/></interface></node>)XML";text(&out,xml);
 }else if(iface=="org.freedesktop.DBus.Properties"&&method=="GetAll")allprops(&out,menu);
 else if(iface=="org.freedesktop.DBus.Properties"&&method=="Get"){
  dbus_message_iter_next(&in);const char*name;dbus_message_iter_get_basic(&in,&name);
  auto temp=dbus_message_new_signal("/","org.neko.Temporary","Properties");DBusMessageIter t,a,e,v;dbus_message_iter_init_append(temp,&t);allprops(&t,menu);dbus_message_iter_init(temp,&t);dbus_message_iter_recurse(&t,&a);bool found=false;
  while(dbus_message_iter_get_arg_type(&a)!=DBUS_TYPE_INVALID){dbus_message_iter_recurse(&a,&e);const char*k;dbus_message_iter_get_basic(&e,&k);dbus_message_iter_next(&e);if(!strcmp(k,name)){dbus_message_iter_recurse(&e,&v);char*sig=dbus_message_iter_get_signature(&v);DBusMessageIter dest;dbus_message_iter_open_container(&out,DBUS_TYPE_VARIANT,sig,&dest);int type=dbus_message_iter_get_arg_type(&v);if(type==DBUS_TYPE_STRING||type==DBUS_TYPE_OBJECT_PATH){const char*s;dbus_message_iter_get_basic(&v,&s);text(&dest,s,type);}else if(type==DBUS_TYPE_BOOLEAN){dbus_bool_t b;dbus_message_iter_get_basic(&v,&b);boolean(&dest,b);}else if(type==DBUS_TYPE_UINT32){unsigned u;dbus_message_iter_get_basic(&v,&u);uintv(&dest,u);}else if(string(name).find("Pixmap")!=string::npos)pixmap(&dest,string(name)=="IconPixmap");else if(string(name)=="IconThemePath"){DBusMessageIter ar;dbus_message_iter_open_container(&dest,DBUS_TYPE_ARRAY,"s",&ar);dbus_message_iter_close_container(&dest,&ar);}else{DBusMessageIter st;dbus_message_iter_open_container(&dest,DBUS_TYPE_STRUCT,nullptr,&st);text(&st,"");pixmap(&st,false);text(&st,"Nekobox YTM");text(&st,phase);dbus_message_iter_close_container(&dest,&st);}dbus_message_iter_close_container(&out,&dest);dbus_free(sig);found=true;break;}dbus_message_iter_next(&a);}
  dbus_message_unref(temp);if(!found){dbus_message_unref(reply);send(dbus_message_new_error(m,DBUS_ERROR_UNKNOWN_PROPERTY,"Неизвестное свойство"));return DBUS_HANDLER_RESULT_HANDLED;}
 }else if(!menu&&(method=="Activate"||method=="SecondaryActivate"))emit("окно");
 else if(!menu&&(method=="ContextMenu"||method=="Scroll")){}
 else if(menu&&method=="GetLayout"){int id=0,depth=-1;dbus_message_iter_get_basic(&in,&id);dbus_message_iter_next(&in);dbus_message_iter_get_basic(&in,&depth);uintv(&out,revision);layout(&out,id,depth);}
 else if(menu&&method=="GetGroupProperties"){DBusMessageIter a,ids,st;dbus_message_iter_open_container(&out,DBUS_TYPE_ARRAY,"(ia{sv})",&a);dbus_message_iter_recurse(&in,&ids);while(dbus_message_iter_get_arg_type(&ids)==DBUS_TYPE_INT32){int id;dbus_message_iter_get_basic(&ids,&id);dbus_message_iter_open_container(&a,DBUS_TYPE_STRUCT,nullptr,&st);integer(&st,id);itemprops(&st,id);dbus_message_iter_close_container(&a,&st);dbus_message_iter_next(&ids);}dbus_message_iter_close_container(&out,&a);}
 else if(menu&&method=="GetProperty"){int id;const char*name;dbus_message_iter_get_basic(&in,&id);dbus_message_iter_next(&in);dbus_message_iter_get_basic(&in,&name);DBusMessageIter v;bool flag=string(name)=="enabled"||string(name)=="visible";dbus_message_iter_open_container(&out,DBUS_TYPE_VARIANT,flag?"b":"s",&v);if(flag)boolean(&v,string(name)=="visible"||id!=3||selected||phase!="Отключено");else text(&v,string(name)=="label"?label(id):id==2||id==4?"separator":"");dbus_message_iter_close_container(&out,&v);}
 else if(menu&&method=="AboutToShow")boolean(&out,false);
 else if(menu&&(method=="AboutToShowGroup"||method=="EventGroup")){if(method=="EventGroup"){DBusMessageIter a,s;dbus_message_iter_recurse(&in,&a);while(dbus_message_iter_get_arg_type(&a)==DBUS_TYPE_STRUCT){dbus_message_iter_recurse(&a,&s);int id;const char*ev;dbus_message_iter_get_basic(&s,&id);dbus_message_iter_next(&s);dbus_message_iter_get_basic(&s,&ev);if(!strcmp(ev,"clicked"))action(id);dbus_message_iter_next(&a);}}for(int n=0;n<(method=="AboutToShowGroup"?2:1);n++){DBusMessageIter a;dbus_message_iter_open_container(&out,DBUS_TYPE_ARRAY,"i",&a);dbus_message_iter_close_container(&out,&a);}}
 else if(menu&&method=="Event"){int id;const char*event;dbus_message_iter_get_basic(&in,&id);dbus_message_iter_next(&in);dbus_message_iter_get_basic(&in,&event);if(!strcmp(event,"clicked"))action(id);}
 else{dbus_message_unref(reply);send(dbus_message_new_error(m,DBUS_ERROR_UNKNOWN_METHOD,"Неизвестный метод"));return DBUS_HANDLER_RESULT_HANDLED;}
 send(reply);return DBUS_HANDLER_RESULT_HANDLED;
}
static int probe(const string&name,const string&mode){
 bool activate=mode=="activate",menu=mode=="menu";auto m=dbus_message_new_method_call(name.c_str(),activate?"/StatusNotifierItem":"/MenuBar",activate?"org.kde.StatusNotifierItem":menuIface,activate?"Activate":menu?"GetLayout":"Event");DBusMessageIter i,a,v;dbus_message_iter_init_append(m,&i);
 if(activate){integer(&i,0);integer(&i,0);}else if(menu){integer(&i,0);integer(&i,-1);dbus_message_iter_open_container(&i,DBUS_TYPE_ARRAY,"s",&a);dbus_message_iter_close_container(&i,&a);}else{integer(&i,mode=="open"?1:mode=="toggle"?3:5);text(&i,"clicked");dbus_message_iter_open_container(&i,DBUS_TYPE_VARIANT,"s",&v);text(&v,"");dbus_message_iter_close_container(&i,&v);uintv(&i,0);}
 DBusError err;dbus_error_init(&err);auto reply=dbus_connection_send_with_reply_and_block(bus,m,3000,&err);dbus_message_unref(m);if(!reply){std::cerr<<"Ошибка D-Bus: "<<(err.message?err.message:"")<<std::endl;return 2;}if(menu){if(strcmp(dbus_message_get_signature(reply),"u(ia{sv}av)"))return 3;DBusMessageIter r,s,c;dbus_message_iter_init(reply,&r);dbus_message_iter_next(&r);dbus_message_iter_recurse(&r,&s);dbus_message_iter_next(&s);dbus_message_iter_next(&s);dbus_message_iter_recurse(&s,&c);int count=0;while(dbus_message_iter_get_arg_type(&c)==DBUS_TYPE_VARIANT){count++;dbus_message_iter_next(&c);}if(count!=5)return 4;std::cout<<"DBusMenu: получены пять пунктов настоящего меню"<<std::endl;}dbus_message_unref(reply);return 0;
}
int main(int argc,char**argv){
 DBusError err;dbus_error_init(&err);bus=dbus_bus_get(DBUS_BUS_SESSION,&err);if(!bus){std::cerr<<"Недоступна шина сеанса D-Bus"<<std::endl;return 1;}
 if(argc==4&&string(argv[1])=="--test")return probe(argv[2],argv[3]);
 if(argc<2)return 1;prctl(PR_SET_PDEATHSIG,SIGTERM);if(getppid()==1)return 1;
 std::ifstream f(argv[1],std::ios::binary);pixels.assign(std::istreambuf_iterator<char>(f),{});if(pixels.size()!=64*64*4)return 1;
 service="org.kde.StatusNotifierItem-"+std::to_string(getpid())+"-1";if(dbus_bus_request_name(bus,service.c_str(),DBUS_NAME_FLAG_DO_NOT_QUEUE,&err)!=DBUS_REQUEST_NAME_REPLY_PRIMARY_OWNER)return 1;
 DBusObjectPathVTable table={};table.message_function=handle;dbus_connection_register_object_path(bus,"/StatusNotifierItem",&table,nullptr);dbus_connection_register_object_path(bus,"/MenuBar",&table,nullptr);
 auto m=dbus_message_new_method_call("org.kde.StatusNotifierWatcher","/StatusNotifierWatcher","org.kde.StatusNotifierWatcher","RegisterStatusNotifierItem");const char*s=service.c_str();dbus_message_append_args(m,DBUS_TYPE_STRING,&s,DBUS_TYPE_INVALID);auto reply=dbus_connection_send_with_reply_and_block(bus,m,3000,&err);dbus_message_unref(m);if(!reply)return 2;dbus_message_unref(reply);std::cout<<"готово\t"<<service<<std::endl;
 string input;while(running&&dbus_connection_get_is_connected(bus)){dbus_connection_read_write(bus,0);while(dbus_connection_dispatch(bus)==DBUS_DISPATCH_DATA_REMAINS){}pollfd fd={STDIN_FILENO,POLLIN|POLLHUP,0};if(poll(&fd,1,30)>0){if(fd.revents&POLLHUP)break;char buf[2048];auto n=read(STDIN_FILENO,buf,sizeof(buf));if(n<=0)break;input.append(buf,n);size_t pos;while((pos=input.find('\n'))!=string::npos){string line=input.substr(0,pos);input.erase(0,pos+1);if(line=="стоп"){running=false;break;}auto tab=line.find('\t');if(tab!=string::npos){phase=line.substr(0,tab);selected=line.substr(tab+1)=="1";changed();}}}}
 dbus_bus_release_name(bus,service.c_str(),nullptr);return 0;
}
